#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (defines DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "mvt.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Array initialization translated to Halide.
 *
 * Original C:
 *   for (i = 0; i < n; i++) {
 *     x1[i]  = (DATA_TYPE) (i % n) / n;
 *     x2[i]  = (DATA_TYPE) ((i + 1) % n) / n;
 *     y_1[i] = (DATA_TYPE) ((i + 3) % n) / n;
 *     y_2[i] = (DATA_TYPE) ((i + 4) % n) / n;
 *     for (j = 0; j < n; j++)
 *       A[i][j] = (DATA_TYPE) (i*j % n) / n;
 *   }
 *
 * We map A[i][j] (row-major C) to Halide as A(j, i), i.e. j -> dim 0 (x), i -> dim 1 (y).
 */
static
void init_array(int n,
                Halide::Buffer<num_t, 1> x1,
                Halide::Buffer<num_t, 1> x2,
                Halide::Buffer<num_t, 1> y_1,
                Halide::Buffer<num_t, 1> y_2,
                Halide::Buffer<num_t, 2> A) {
    Var i("i"), j("j");

    Func init_x1("init_x1");
    Func init_x2("init_x2");
    Func init_y1("init_y1");
    Func init_y2("init_y2");
    Func init_A("init_A");

    // Common denominator as Expr, in the element type
    Expr n_expr = cast<num_t>(n);

    // 1D vectors
    init_x1(i) = cast<num_t>(i % n)         / n_expr;
    init_x2(i) = cast<num_t>((i + 1) % n)   / n_expr;
    init_y1(i) = cast<num_t>((i + 3) % n)   / n_expr;
    init_y2(i) = cast<num_t>((i + 4) % n)   / n_expr;

    // 2D matrix A: C layout A[i][j] -> Halide A(j, i)
    init_A(j, i) = cast<num_t>((i * j) % n) / n_expr;

    // Simple but effective schedule for initialization:
    // - vectorize along the contiguous dimension
    // - parallelize across the outer dimension
    const int vec_width = 8;  // tunable; 8 works well on modern x86

    init_x1
        .compute_root()
        .vectorize(i, vec_width)
        .parallel(i);

    init_x2
        .compute_root()
        .vectorize(i, vec_width)
        .parallel(i);

    init_y1
        .compute_root()
        .vectorize(i, vec_width)
        .parallel(i);

    init_y2
        .compute_root()
        .vectorize(i, vec_width)
        .parallel(i);

    // A(j, i): j is contiguous (dim 0), so vectorize over j, parallelize over i.
    init_A
        .compute_root()
        .vectorize(j, vec_width)
        .parallel(i);

    // Realize into the provided buffers
    init_x1.realize(x1);
    init_x2.realize(x2);
    init_y1.realize(y_1);
    init_y2.realize(y_2);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to:
    //   DATA_TYPE A[N][N];
    //   DATA_TYPE x1[N], x2[N], y_1[N], y_2[N];
    //
    // PolyBench uses A[i][j]; we map j -> dim 0 (x), i -> dim 1 (y).
    Halide::Buffer<num_t, 2> A(n, n);     // (j, i)
    Halide::Buffer<num_t, 1> x1(n);
    Halide::Buffer<num_t, 1> x2(n);
    Halide::Buffer<num_t, 1> y_1(n);
    Halide::Buffer<num_t, 1> y_2(n);

    // ImageParams to feed into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x1_param(type_of<num_t>(), 1, "x1_param");
    ImageParam x2_param(type_of<num_t>(), 1, "x2_param");
    ImageParam y1_param(type_of<num_t>(), 1, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 1, "y2_param");

    // Initialize data using a Halide-based initializer
    init_array(n, x1, x2, y_1, y_2, A);

    // Bind buffers to ImageParams
    A_param.set(A);
    x1_param.set(x1);
    x2_param.set(x2);
    y1_param.set(y_1);
    y2_param.set(y_2);

    // Halide translation of kernel_mvt:
    //
    // Original C kernel:
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x1[i] = x1[i] + A[i][j] * y_1[j];
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x2[i] = x2[i] + A[j][i] * y_2[j];
    //
    // Mathematically:
    //   x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
    //   x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
    //
    // With our (j, i) mapping for A[i][j]:
    //   A[i][j]  -> A_param(j, i)
    //   A[j][i]  -> A_param(i, j)

    Var i("i");
    // Use the width of A (dim 0, corresponding to j) as the reduction extent.
    RDom r(0, A.dim(0).extent(), "r");

    Func mvt_x1("mvt_x1");
    Func mvt_x2("mvt_x2");

    // First loop nest: accumulate into x1
    //
    // x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
    //        = x1_param(i) + sum_r A_param(r, i) * y1_param(r)
    mvt_x1(i) = x1_param(i);
    mvt_x1(i) += A_param(r, i) * y1_param(r);

    // Second loop nest: accumulate into x2
    //
    // x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
    //        = x2_param(i) + sum_r A_param(i, r) * y2_param(r)
    mvt_x2(i) = x2_param(i);
    mvt_x2(i) += A_param(i, r) * y2_param(r);

    // --------------------------------------------------------------------
    // Scheduling for performance
    // --------------------------------------------------------------------
    //
    // We target:
    //   - Parallelism across i (each output element is independent).
    //   - Vectorization along a unit-stride dimension.
    //   - Reasonable defaults that work well on a modern x64 CPU.
    //
    // Note: for the reduction update, the default loop nest is:
    //   for r:
    //     for i:
    //       mvt_x*(i) += ...
    //
    // We reorder to:
    //   for i (parallel):
    //     for r (vectorized):
    //       ...
    //
    // to make i outermost (for parallelism) and r innermost (for
    // contiguous access to A_param(r, i) in the x1 case).

    const int vec_width = 8;  // tunable vector width

    // x1 pipeline: good locality on A_param(r, i) when r is innermost.
    mvt_x1.compute_root();
    // Pure step: vectorize & parallelize across i.
    mvt_x1
        .vectorize(i, vec_width)
        .parallel(i);
    // Reduction update: make i outermost, r innermost; parallelize over i,
    // and vectorize over r (unit-stride for A_param(r, i)).
    mvt_x1.update()
        .reorder(r, i)          // loops: for i (outer), for r (inner)
        .vectorize(r, vec_width)
        .parallel(i);

    // x2 pipeline: same parallel pattern; A_param(i, r) access is
    // strided in r, but we still get parallelism across i.
    mvt_x2.compute_root();
    mvt_x2
        .vectorize(i, vec_width)
        .parallel(i);
    mvt_x2.update()
        .reorder(r, i)
        .vectorize(r, vec_width)
        .parallel(i);

    // Explicitly JIT-compile once before timing to avoid counting
    // compilation time in the measured interval.
    Target target = get_jit_target_from_environment();
    mvt_x1.compile_jit(target);
    mvt_x2.compile_jit(target);

    // Use separate output buffers to avoid any potential aliasing
    // between input ImageParams and outputs.
    Halide::Buffer<num_t, 1> x1_out(n);
    Halide::Buffer<num_t, 1> x2_out(n);

    // Time the kernel execution (both x1 and x2 updates)
    auto start = std::chrono::high_resolution_clock::now();

    // Realize into the output buffers
    mvt_x1.realize(x1_out);
    mvt_x2.realize(x2_out);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results to stderr (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print x1
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x1_out(idx) << '\n';
        }
        // Print x2
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x2_out(idx) << '\n';
        }
    }

    // Print timing (seconds) to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
