    // A simple but cache-friendly schedule for initialization:
    // - Parallelize over i for vectors.
    // - For A, parallelize over i (rows) and vectorize across j (contiguous).
    Target t = get_host_target();
    const int vec = std::max(1, t.natural_vector_size(type_of<num_t>()));

    Var io("io"), ii("ii");

    init_x1
        .compute_root()
        .split(i, io, ii, 1024)
        .vectorize(ii, vec)
        .parallel(io);

    init_x2
        .compute_root()
        .split(i, io, ii, 1024)
        .vectorize(ii, vec)
        .parallel(io);

    init_y1
        .compute_root()
        .split(i, io, ii, 1024)
        .vectorize(ii, vec)
        .parallel(io);

    init_y2
        .compute_root()
        .split(i, io, ii, 1024)
        .vectorize(ii, vec)
        .parallel(io);

    Var jo("jo"), ji("ji");
    init_A
        .compute_root()
        .split(j, jo, ji, 1024)
        .vectorize(ji, vec)
        .parallel(i);

    // Realize into the provided buffers
    init_x1.realize(x1);
    init_x2.realize(x2);
    init_y1.realize(y_1);
    init_y2.realize(y_2);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to:
    //   DATA_TYPE A[N][N];
    //   DATA_TYPE x1[N], x2[N], y_1[N], y_2[N];
    //
    // PolyBench uses A[i][j]; we map j -> dim 0 (x), i -> dim 1 (y).
    Halide::Buffer<num_t, 2> A(n, n);     // (j, i)
    Halide::Buffer<num_t, 1> x1(n);
    Halide::Buffer<num_t, 1> x2(n);
    Halide::Buffer<num_t, 1> y_1(n);
    Halide::Buffer<num_t, 1> y_2(n);

    // ImageParams to feed into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x1_param(type_of<num_t>(), 1, "x1_param");
    ImageParam x2_param(type_of<num_t>(), 1, "x2_param");
    ImageParam y1_param(type_of<num_t>(), 1, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 1, "y2_param");

    // Initialize data using a Halide-based initializer
    init_array(n, x1, x2, y_1, y_2, A);

    // Bind buffers to ImageParams
    A_param.set(A);
    x1_param.set(x1);
    x2_param.set(x2);
    y1_param.set(y_1);
    y2_param.set(y_2);

    // Halide translation of kernel_mvt:
    //
    // Original C kernel:
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x1[i] = x1[i] + A[i][j] * y_1[j];
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x2[i] = x2[i] + A[j][i] * y_2[j];
    //
    // Mathematically:
    //   x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
    //   x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
    //
    // With our (j, i) mapping for A[i][j]:
    //   A[i][j]  -> A_param(j, i)
    //   A[j][i]  -> A_param(i, j)

    Var i("i");
    // Use the width of A (dim 0, corresponding to j) as the reduction extent.
    RDom r(0, A.dim(0).extent(), "r");

    Func mvt_x1("mvt_x1");
    Func mvt_x2("mvt_x2");

    // First loop nest: accumulate into x1
    //   x1[i] = x1[i] + sum_r A_param(r, i) * y1_param(r);
    mvt_x1(i) = x1_param(i);
    mvt_x1(i) += A_param(r, i) * y1_param(r);

    // Second loop nest: accumulate into x2
    //   x2[i] = x2[i] + sum_r A_param(i, r) * y2_param(r);
    mvt_x2(i) = x2_param(i);
    mvt_x2(i) += A_param(i, r) * y2_param(r);

    // ------------------------------------------------------------------
    // Scheduling for performance
    // ------------------------------------------------------------------
    //
    // We optimize data locality and parallelism while preserving
    // the mathematical definition above. We:
    //   - Parallelize across output index i (rows / columns).
    //   - Vectorize across i for mvt_x2 (contiguous in memory).
    //   - Vectorize across the reduction r for mvt_x1 (contiguous in A).
    //   - Use a single Pipeline to JIT once and then realize both x1 and x2.
    //
    Target target = get_host_target();
    const int vec = std::max(1, target.natural_vector_size(type_of<num_t>()));

    // Tuning parameter: number of i-elements per parallel chunk.
    // This is a separate knob so it can be changed to match cache and
    // core topology without touching the algorithm.
    const int i_tile = 256;

    // Schedule for mvt_x1:
    //
    // A_param(r, i) is contiguous in r (dim 0), so we vectorize over r.
    // We also split i so we can parallelize outer chunks.
    {
        Var io("io_x1"), ii("ii_x1");
        RVar ro("ro_x1"), ri("ri_x1");

        // Initialization of x1
        mvt_x1
            .compute_root()
            .split(i, io, ii, i_tile)
            .parallel(io)
            .vectorize(ii, vec);

        // Reduction update:
        //   Outer: io (chunks of i)
        //   Middle: ro (tiles of r)
        //   Inner: ri (vectorized r-lane)
        mvt_x1.update()
            .split(r, ro, ri, vec)          // tile the reduction so 'ri' has length 'vec'
            .split(i, io, ii, i_tile)       // tile i for parallelism
            .reorder(ri, ii, ro, io)        // innermost: ri (vector), then ii, then ro, io
            .parallel(io)
            .vectorize(ri);
    }

    // Schedule for mvt_x2:
    //
    // A_param(i, r) is contiguous in i (dim 0), so we vectorize over i.
    // We use a similar tiling of i for parallelism.
    {
        Var io("io_x2"), ii("ii_x2");

        mvt_x2
            .compute_root()
            .split(i, io, ii, i_tile)
            .parallel(io)
            .vectorize(ii, vec);

        // For the update we want loops over:
        //   io (parallel)
        //   r  (sequential reduction)
        //   ii (vectorized across output elements)
        mvt_x2.update()
            .split(i, io, ii, i_tile)
            .reorder(ii, r, io)
            .parallel(io)
            .vectorize(ii, vec);
    }

    // Build a single pipeline containing both Funcs so that:
    //   - JIT compilation happens once.
    //   - The runtime can potentially fuse work where profitable.
    Pipeline pipeline({mvt_x1, mvt_x2});
    pipeline.compile_jit(target);

    // Time the kernel execution (both x1 and x2 updates)
    auto start = std::chrono::high_resolution_clock::now();

    // Realize back into x1 and x2 buffers (in-place relative to the C view)
    {
        // Use a Realization to pass both output buffers to the pipeline.
        Realization outputs({x1, x2});
        pipeline.realize(outputs);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results to stderr (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print x1
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x1(idx) << '\n';
        }
        // Print x2
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x2(idx) << '\n';
        }
    }

    // Print timing (seconds) to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
