    A_param.set(A);
    x1_param.set(x1);
    x2_param.set(x2);
    y1_param.set(y_1);
    y2_param.set(y_2);

    // Halide translation of kernel_mvt:
    //
    // Original C kernel:
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x1[i] = x1[i] + A[i][j] * y_1[j];
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x2[i] = x2[i] + A[j][i] * y_2[j];
    //
    // Mathematically:
    //   x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
    //   x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
    //
    // With our (j, i) mapping for A[i][j]:
    //   A[i][j]  -> A_param(j, i)
    //   A[j][i]  -> A_param(i, j)

    Var i("i");
    // Use the width of A (dim 0, corresponding to j) as the reduction extent.
    RDom r(0, A.dim(0).extent(), "r");

    Func mvt_x1("mvt_x1");
    Func mvt_x2("mvt_x2");

    // First loop nest: accumulate into x1
    //
    // mvt_x1(i) = x1[i] + sum_j A[i][j] * y_1[j]
    //           = x1_param(i) + sum_r A_param(r, i) * y1_param(r)
    mvt_x1(i) = x1_param(i);
    mvt_x1(i) += A_param(r, i) * y1_param(r);

    // Second loop nest: accumulate into x2
    //
    // mvt_x2(i) = x2[i] + sum_j A[j][i] * y_2[j]
    //           = x2_param(i) + sum_r A_param(i, r) * y2_param(r)
    mvt_x2(i) = x2_param(i);
    mvt_x2(i) += A_param(i, r) * y2_param(r);

    // ------------------------------------------------------------------
    // Scheduling for the MVT kernel
    // ------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = Halide::natural_vector_size<num_t>(target);

    // Compute both results at the root so we can parallelize across i.
    mvt_x1.compute_root();
    mvt_x2.compute_root();

    // Pure definitions (initial copies of x1/x2) are 1D and trivially
    // vectorizable; parallelizing them is safe and cheap.
    mvt_x1
        .vectorize(i, vec_width)
        .parallel(i);
    mvt_x2
        .vectorize(i, vec_width)
        .parallel(i);

    // ---------------------------
    // Schedule for mvt_x1:
    // ---------------------------
    //
    // Access pattern: A_param(r, i)
    //   - A is stored with j mapped to dim 0 (x), which is contiguous.
    //   - r indexes dim 0, so we want r to be the innermost loop
    //     to stream through rows of A and y_1.
    //
    // Default loop nest for the update is:
    //   for i:
    //     for r:
    //       ...
    //
    // This is already good for A and y_1 locality:
    //   - each i sees a contiguous row of A in r
    //   - x1(i) is independent across i, so we parallelize across i
    //   - vectorize across r to use SIMD on the inner reduction
    mvt_x1.update()
        .parallel(i)
        .vectorize(r, vec_width);

    // ---------------------------
    // Schedule for mvt_x2:
    // ---------------------------
    //
    // Access pattern: A_param(i, r)
    //   - i indexes dim 0 (x / contiguous),
    //   - r indexes dim 1 (y / strided by N).
    //
    // With the default order (for i: for r:), we would read A by
    // columns (poor locality). We instead:
    //
    //   * Split i into tiles: i = io * tile_size + ii
    //   * Reorder loops to: for io (outer, parallel), for r, for ii (inner, vectorized)
    //
    // This gives, for the update step:
    //   for io in tiles (parallel) {
    //     for r in 0..N-1 {
    //       for ii in 0..tile_size (vectorized) {
    //         i = io * tile_size + ii;
    //         x2[i] += A(i, r) * y2[r];
    //       }
    //     }
    //   }
    //
    // For fixed r, i varies fastest, so A(i, r) walks the contiguous
    // x-dimension and is also vectorized over ii, improving memory
    // bandwidth compared to the naive strided pattern.
    Var io("io"), ii("ii");
    const int tile_i = 128;  // tile size for i; tunable

    mvt_x2.update()
        .split(i, io, ii, tile_i)
        .reorder(ii, r, io)   // innermost: ii, then r, then io outermost
        .parallel(io)         // parallel over tiles of i
        .vectorize(ii, vec_width);

    // JIT-compile the two Funcs with the chosen target
    mvt_x1.compile_jit(target);
    mvt_x2.compile_jit(target);

    // Time the kernel execution (both x1 and x2 updates)
    auto start = std::chrono::high_resolution_clock::now();

    // Realize back into x1 and x2 buffers (in-place relative to the C view)
    mvt_x1.realize(x1);
    mvt_x2.realize(x2);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results to stderr (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print x1
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x1(idx) << '\n';
        }
        // Print x2
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x2(idx) << '\n';
        }
    }

    // Print timing (seconds) to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
