    mvt_x2(i) += A_param(i, r) * y2_param(r);

    // ------------------------------------------------------------------
    // Scheduling for performance
    // ------------------------------------------------------------------
    //
    // We optimize for:
    //   - Good cache behavior (streaming in A and y_*).
    //   - Parallelism over the outer i-dimension.
    //   - Reasonable vectorization on the row-friendly multiply (x1).
    //
    // Both reductions are of the form:
    //   out(i) = out(i) + sum_r ( ... )
    // so i is independent and safe to parallelize.

    Target target = get_host_target();

    // Tile size for parallelizing the i-dimension. This can be tuned
